fn reject_symlink(path: &Path, label: &str) -> Result<(), AppError> {
    if crate::atomic_file::is_symlink(path) {
        return Err(AppError::Config(format!(
            "{label} `{}` is a symlink; refusing to write for security",
            path.display()
        )));
    }
    Ok(())
}

